CREATE TABLE grc.grc_incident (
    id uuid NOT NULL,
    incident_number character varying(50) NOT NULL,
    incident_type character varying(40) NOT NULL,
    title character varying(255) NOT NULL,
    description text,
    reported_by_employee_id uuid NOT NULL,
    owner_employee_id uuid,
    customer_id uuid,
    department_id uuid,
    risk_id uuid,
    control_id uuid,
    severity character varying(20),
    occurred_at timestamp with time zone,
    detected_at timestamp with time zone,
    helpdesk_ticket_id uuid,
    service_request_id uuid,
    project_id uuid,
    quality_nonconformance_id uuid,
    asset_id uuid,
    document_id uuid,
    finance_journal_id uuid,
    status character varying(30) NOT NULL,
    workflow_status character varying(30),
    workflow_instance_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    tenant_id uuid NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ck_grc_incident_severity CHECK (((severity IS NULL) OR ((severity)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text])))),
    CONSTRAINT ck_grc_incident_status CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('submitted'::character varying)::text, ('under_review'::character varying)::text, ('open'::character varying)::text, ('contained'::character varying)::text, ('resolved'::character varying)::text, ('closed'::character varying)::text, ('cancelled'::character varying)::text]))),
    CONSTRAINT ck_grc_incident_type CHECK (((incident_type)::text = ANY (ARRAY[('compliance'::character varying)::text, ('security'::character varying)::text, ('operational'::character varying)::text, ('safety'::character varying)::text, ('fraud'::character varying)::text, ('other'::character varying)::text])))
);


